const m = global.get('metrics') || {};
msg.statusCode = 200;
msg.payload = {
    status: 'ok',
    service: 'industrial-ingestion',
    modbus_published_total: m.facis_inding_modbus_published_total || 0,
    opcua_published_total: m.facis_inding_opcua_published_total || 0,
    dlq_total: m.facis_inding_dlq_total || {},
    timestamp: new Date().toISOString()
};
return msg;

return {
    payload: {
        error_type: 'uncaught',
        error_message: msg && msg.error ? (msg.error.message || String(msg.error)) : 'unknown error',
        error_timestamp: new Date().toISOString(),
        source_protocol: null,
        device_id: null,
        original_envelope: null
    }
};
